/*
 * mkrusttests.c -- turn a reference dump into a Rust test module.
 *
 * The dump is the oracle: it is what a real machine's VDI did, case by case.
 * This emits one `#[test]` per case that replays the case against
 * `tos_api::vdi::dispatch` and compares every array against the record. The
 * comparison itself lives in the harness; this only lays out the inputs and
 * the record index, so the generated file stays readable and reviewable.
 *
 * The expected outputs are NOT copied into the generated code: it embeds the
 * dump with `include_bytes!` and indexes into it. The dump therefore stays
 * the single source of truth, and regenerating after a new measurement
 * cannot leave stale expectations behind.
 *
 * usage: mkrusttests CASES.TSV DUMP.BIN DUMP_INCLUDE_PATH OUT.rs
 */
#include <stdio.h>
#include <stdlib.h>
#include <string.h>

#include "cases.h"

static struct td_case_table table;

/* A Rust identifier fragment from a free-text comment. */
static void slug(const char *s, char *out, size_t out_size)
{
	size_t n = 0;
	int prev_us = 1;   /* suppress a leading underscore */

	for (; *s && n + 1 < out_size; s++) {
		char c = *s;
		if ((c >= 'a' && c <= 'z') || (c >= '0' && c <= '9')) {
			out[n++] = c;
			prev_us = 0;
		} else if (c >= 'A' && c <= 'Z') {
			out[n++] = (char)(c - 'A' + 'a');
			prev_us = 0;
		} else if (!prev_us) {
			out[n++] = '_';
			prev_us = 1;
		}
	}
	while (n > 0 && out[n - 1] == '_')
		n--;
	out[n] = '\0';
	if (n == 0)
		snprintf(out, out_size, "case");
}

static void escape(const char *s, char *out, size_t out_size)
{
	size_t n = 0;

	for (; *s && n + 2 < out_size; s++) {
		if (*s == '"' || *s == '\\')
			out[n++] = '\\';
		out[n++] = *s;
	}
	out[n] = '\0';
}

static void emit_list(FILE *f, const int16_t *v, uint16_t n)
{
	uint16_t i;

	if (n == 0) {
		fputs("&[]", f);
		return;
	}
	fputs("&[", f);
	for (i = 0; i < n; i++)
		fprintf(f, "%s%d", i ? ", " : "", v[i]);
	fputc(']', f);
}

int main(int argc, char **argv)
{
	struct td_case_error err;
	struct td_header h;
	uint8_t hdr[TD_HEADER_SIZE];
	const char *cases_path, *dump_path, *include_path, *out_path;
	FILE *fd, *f;
	uint16_t i;
	int rc;

	if (argc != 5) {
		fprintf(stderr, "usage: mkrusttests CASES.TSV DUMP.BIN "
		                "DUMP_INCLUDE_PATH OUT.rs\n");
		return 2;
	}
	cases_path = argv[1];
	dump_path = argv[2];
	include_path = argv[3];
	out_path = argv[4];

	memset(&err, 0, sizeof err);
	rc = td_cases_load(&table, cases_path, &err);
	if (rc != 0) {
		fprintf(stderr, "%s: %s\n", cases_path, td_case_error_text(rc));
		return 1;
	}

	fd = fopen(dump_path, "rb");
	if (!fd || fread(hdr, 1, sizeof hdr, fd) != sizeof hdr) {
		fprintf(stderr, "%s: cannot read the dump header\n", dump_path);
		if (fd) fclose(fd);
		return 1;
	}
	fclose(fd);
	rc = td_header_parse(hdr, sizeof hdr, &h);
	if (rc != 0) {
		fprintf(stderr, "%s: malformed header (%d)\n", dump_path, rc);
		return 1;
	}

	/* Refuse rather than generate nonsense: a dump taken with a different
	 * case table has different case ids at every index. */
	if (h.case_crc != table.crc) {
		fprintf(stderr,
		        "refusing: %s carries case table CRC %08X, %s is %08X -- the "
		        "dump was not produced from this table\n",
		        dump_path, h.case_crc, cases_path, table.crc);
		return 2;
	}
	if (h.record_count != table.count) {
		fprintf(stderr, "refusing: %s holds %u records, %s holds %u cases\n",
		        dump_path, h.record_count, cases_path, table.count);
		return 2;
	}
	if (h.area != TD_AREA_VDI) {
		fprintf(stderr, "refusing: %s is area %s, not VDI\n", dump_path,
		        td_area_name(h.area));
		return 2;
	}

	f = fopen(out_path, "wb");
	if (!f) {
		perror(out_path);
		return 1;
	}

	fprintf(f,
"//! GENERATED by tosdump/host/mkrusttests -- do not edit.\n"
"//!\n"
"//! One test per case in `%s`, replayed against `tos_api::vdi` and\n"
"//! compared with what a real machine did, recorded in `%s`\n"
"//! (build %s, case table CRC %08X, %u cases).\n"
"//!\n"
"//! The expected values are not written out here: the dump is embedded and\n"
"//! indexed, so it stays the single source of truth and a regenerated file\n"
"//! cannot carry stale expectations. Regenerate with:\n"
"//!\n"
"//!     tosdump/host/build/mkrusttests \\\\\n"
"//!         tosdump/%s \\\\\n"
"//!         tosdump/%s \\\\\n"
"//!         %s \\\\\n"
"//!         tos-api/tests/vdi_reference/cases_r2.rs\n"
"\n"
"use crate::harness::{check, Call, Case};\n"
"\n"
"static DUMP: &[u8] = include_bytes!(\"%s\");\n",
	        cases_path, dump_path, h.build_id, h.case_crc, h.record_count,
	        cases_path, dump_path, include_path, include_path);

	for (i = 0; i < table.count; i++) {
		const struct td_case *c = &table.cases[i];
		char name[96], cmt[TD_COMMENT_LEN * 2];

		slug(c->comment, name, sizeof name);
		escape(c->comment, cmt, sizeof cmt);

		fprintf(f, "\n#[test]\nfn case_%04u_op%03d", c->line, c->opcode);
		if (c->sub)
			fprintf(f, "_sub%d", c->sub);
		fprintf(f, "_%s() {\n", name);
		fprintf(f, "    check(DUMP, &Case {\n");
		fprintf(f, "        prelude: &[");
		{
			uint16_t k;
			for (k = 0; k < c->prelude_count; k++) {
				const struct td_prelude *p =
					&table.preludes[c->prelude_first + k];
				fprintf(f, "\n            Call { opcode: %d, sub: %d, intin: ",
				        p->opcode, p->sub);
				emit_list(f, p->intin, p->n_intin);
				fprintf(f, ", ptsin: ");
				emit_list(f, p->ptsin, p->n_ptsin);
				fprintf(f, " },");
			}
			if (c->prelude_count)
				fprintf(f, "\n        ");
		}
		fprintf(f, "],\n");
		fprintf(f, "        id: %u,\n        rec: %u,\n", c->line, i);
		fprintf(f, "        opcode: %d,\n        sub: %d,\n", c->opcode, c->sub);
		fprintf(f, "        intin: ");
		emit_list(f, c->intin, c->n_intin);
		fprintf(f, ",\n        ptsin: ");
		emit_list(f, c->ptsin, c->n_ptsin);
		fprintf(f, ",\n        comment: \"%s\",\n    });\n}\n", cmt);
	}

	fclose(f);
	printf("%s: %u tests from %s\n", out_path, table.count, dump_path);
	return 0;
}
